CREATE TABLE publishers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE books (id INTEGER PRIMARY KEY AUTOINCREMENT, isbn13 TEXT NOT NULL, title TEXT NOT NULL, subtitle TEXT, author_display TEXT NOT NULL, publisher_id INTEGER REFERENCES publishers(id), published_at TEXT, cover_url TEXT, description TEXT, page_count INTEGER, primary_category TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX books_isbn13_unique ON books(isbn13);
CREATE TABLE authors (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE book_authors (book_id INTEGER NOT NULL REFERENCES books(id), author_id INTEGER NOT NULL REFERENCES authors(id), role TEXT NOT NULL DEFAULT 'author', PRIMARY KEY(book_id, author_id, role));
CREATE TABLE people (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, occupation TEXT, profile_image_url TEXT, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sources (id INTEGER PRIMARY KEY AUTOINCREMENT, source_type TEXT NOT NULL, title TEXT NOT NULL, publisher_or_channel TEXT, url TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE book_mentions (id INTEGER PRIMARY KEY AUTOINCREMENT, book_id INTEGER NOT NULL REFERENCES books(id), person_id INTEGER NOT NULL REFERENCES people(id), source_id INTEGER NOT NULL REFERENCES sources(id), relation_type TEXT NOT NULL CHECK(relation_type IN ('recommended','favorite','influential','reading','mentioned','selected')), commercial_context TEXT NOT NULL DEFAULT 'unknown' CHECK(commercial_context IN ('organic','sponsored','gifted','publisher_event','unknown')), confidence TEXT NOT NULL DEFAULT 'low' CHECK(confidence IN ('high','medium','low')), context_summary TEXT, verified INTEGER NOT NULL DEFAULT 0, verified_at TEXT, disclosure_stated INTEGER, organizer_type TEXT CHECK(organizer_type IN ('publisher','bookstore','independent','other')), voluntary_mention INTEGER, repeat_mention_group TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE collections (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, collection_type TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE collection_books (collection_id INTEGER NOT NULL REFERENCES collections(id), book_id INTEGER NOT NULL REFERENCES books(id), score REAL, reason TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(collection_id, book_id));
CREATE TABLE book_rankings (id INTEGER PRIMARY KEY AUTOINCREMENT, book_id INTEGER NOT NULL REFERENCES books(id), provider TEXT NOT NULL, ranking_type TEXT NOT NULL, rank INTEGER NOT NULL, recorded_date TEXT NOT NULL, category TEXT);
CREATE TABLE user_libraries (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, library_code TEXT NOT NULL, library_name TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
